import os, re, json, time
import numpy as np

# ---- Config ----
N = 26
SNAP_C = 'storage/noesis/latest_centers.txt'
SNAP_R = 'storage/noesis/latest_radii.txt'
SHARED_DIR = 'storage/shared/appxE_contribs'
LINEAGE_SCAN_ROOTS = ['storage/scientia']  # may scan others in future
OUT_DIR = 'storage/noesis/nmap/results'
SUMMARY_PATH = 'storage/noesis/nmap/appendix_E_summary_v2_1.json'
FREEZE_DIR = 'storage/noesis/nmap/freezes'
K_GRID = [15, 25, 40, 60]
TOLS = [1e-9, 1e-8]

# ---- IO utils ----
def ts():
    return time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())

def safe_mkdir(p):
    os.makedirs(p, exist_ok=True)

def write_json(path, obj):
    safe_mkdir(os.path.dirname(path))
    with open(path, 'w') as f:
        json.dump(obj, f, indent=2)

def load_json(path):
    with open(path, 'r') as f:
        return json.load(f)

# ---- Baseline snapshot ----
def load_snapshot():
    if os.path.exists(SNAP_C) and os.path.exists(SNAP_R):
        c = np.loadtxt(SNAP_C, dtype=float).reshape(N, 2)
        r = np.loadtxt(SNAP_R, dtype=float).reshape(N,)
        return c, r
    # Fallback: small, safe grid+hole layout
    centers = []
    radius = 0.08
    for i in range(5):
        for j in range(6):
            if len(centers) < 26:
                x = 0.1 + i * 0.2
                y = 0.1 + j * 0.15
                centers.append([x, y])
    return np.array(centers, float), np.full(N, radius, float)

# ---- Geometry helpers ----
def slacks(c, r):
    diff = c[:,None,:] - c[None,:,:]
    dist = np.sqrt(np.sum(diff**2, axis=2))
    s_pairs = dist - (r[:,None] + r[None,:])
    x = c[:,0]; y = c[:,1]
    s_xL = x - r
    s_xR = 1.0 - x - r
    s_yB = y - r
    s_yT = 1.0 - y - r
    return (s_xL, s_xR, s_yB, s_yT), s_pairs

def boundary_mask(c, r, tol):
    (s_xL, s_xR, s_yB, s_yT), _ = slacks(c, r)
    return (s_xL <= tol) | (s_xR <= tol) | (s_yB <= tol) | (s_yT <= tol)

def topk_interior_pairs(c, r, tol, K):
    (_, _, _, _), sp = slacks(c, r)
    bmask = boundary_mask(c, r, tol)
    pairs = []
    for i in range(N):
        for j in range(i+1, N):
            if bmask[i] or bmask[j]:
                continue
            pairs.append((i, j, float(sp[i, j])))
    pairs.sort(key=lambda t: t[2])
    return [(i, j) for (i, j, _) in pairs[:K]]

def jaccard(a_pairs, b_pairs):
    A = set(tuple(sorted(p)) for p in a_pairs)
    B = set(tuple(sorted(p)) for p in b_pairs)
    if not A and not B:
        return 1.0
    if not A or not B:
        return 0.0
    inter = len(A & B); uni = len(A | B)
    return inter / uni if uni > 0 else 1.0

# ---- Parse index maps (to Noesis) ----
def parse_index_maps():
    maps = {}  # class_key -> list of 26 ints
    if not os.path.isdir(SHARED_DIR):
        return maps
    for fn in os.listdir(SHARED_DIR):
        if fn.endswith('_index_map_to_noesis.json'):
            path = os.path.join(SHARED_DIR, fn)
            try:
                data = load_json(path)
                perm = None
                if isinstance(data, dict) and isinstance(data.get('index_map_to_noesis'), list):
                    perm = data['index_map_to_noesis']
                elif isinstance(data, list) and len(data) == 26:
                    perm = data
                if isinstance(perm, list) and len(perm) == 26 and all(isinstance(x, int) for x in perm):
                    key = re.sub(r'_index_map_to_noesis\.json$', '', fn)
                    # normalize class_key: drop leading lineage prefix if present
                    key = re.sub(r'^scientia_', '', key)
                    maps[key] = perm
            except Exception:
                continue
    return maps

# ---- Discover Top-K slack files ----
TOPK_PAT = re.compile(r'(encourage_[0-9]+_[0-9]+_eval[0-9]+)', re.IGNORECASE)
def tol_from_name(name):
    s = name.replace('_', '').lower()
    if '1em09' in s or '1e-9' in s or '1e09' in s or '1e9' in s:
        return 1e-9
    if '1em08' in s or '1e-8' in s or '1e08' in s or '1e8' in s:
        return 1e-8
    return None

def K_from_name(name, default_len=None):
    m = re.search(r'K(\d+)', name, re.IGNORECASE)
    if m:
        try:
            return int(m.group(1))
        except Exception:
            pass
    return default_len

def extract_class_key(name):
    m = TOPK_PAT.search(name)
    if m:
        return m.group(1)
    # fallback: strip lineage prefix and suffix
    base = os.path.basename(name)
    base = base.replace('scientia_', '')
    return os.path.splitext(base)[0]

def parse_pairs_from_json(data):
    # Accept either list of [i,j] or dict with 'pairs'
    if isinstance(data, list):
        return [tuple(map(int, p)) for p in data if isinstance(p, (list, tuple)) and len(p) == 2]
    if isinstance(data, dict):
        if isinstance(data.get('pairs'), list):
            return [tuple(map(int, p)) for p in data['pairs'] if isinstance(p, (list, tuple)) and len(p) == 2]
        # legacy keys: 'slack_top_k_...': recurse grab any list values
        out = []
        for v in data.values():
            if isinstance(v, list) and v and isinstance(v[0], (list, tuple)):
                try:
                    out.extend([tuple(map(int, p)) for p in v])
                except Exception:
                    pass
        if out:
            return out
    return []

def scan_topk_files():
    entries = []  # list of dicts: {class_key, eval_id, tol, K, pairs}
    # Scan shared first
    roots = [SHARED_DIR] if os.path.isdir(SHARED_DIR) else []
    # Then lineage roots
    for r in LINEAGE_SCAN_ROOTS:
        if os.path.isdir(r):
            roots.append(r)
    for root in roots:
        for walk_root, _, files in os.walk(root):
            for fn in files:
                if not fn.lower().endswith('.json'):
                    continue
                name = fn.lower()
                # Heuristic filter for top-k slack files
                if ('slack_top_k' not in name) and ('top_k' not in name):
                    continue
                p = os.path.join(walk_root, fn)
                try:
                    data = load_json(p)
                except Exception:
                    continue
                pairs = parse_pairs_from_json(data)
                if not pairs:
                    continue
                tol = tol_from_name(name)
                K_guess = K_from_name(name, default_len=len(pairs))
                class_key = extract_class_key(p)
                # Try to get eval id
                m = re.search(r'eval(\d+)', class_key, re.IGNORECASE)
                eval_id = int(m.group(1)) if m else None
                entries.append({
                    'path': p,
                    'class_key': class_key,
                    'eval_id': eval_id,
                    'tol': tol,
                    'K': K_guess,
                    'pairs': pairs
                })
    return entries

def apply_index_map(pairs, perm):
    if not perm:
        return [tuple(sorted(p)) for p in pairs]
    mapped = []
    try:
        for (i, j) in pairs:
            ii = int(perm[i]); jj = int(perm[j])
            mapped.append(tuple(sorted((ii, jj))))
    except Exception:
        # fallback: return as-is if map fails
        mapped = [tuple(sorted(p)) for p in pairs]
    return mapped

# ---- Aggregation and comparison ----
def aggregate_and_compare(c0, r0):
    # Prepare my internal Top-K sets
    mine = {(tol, K): topk_interior_pairs(c0, r0, tol=tol, K=K) for tol in TOLS for K in K_GRID}

    # Load maps and entries
    index_maps = parse_index_maps()
    entries = scan_topk_files()

    # Organize by class_key and tol,K
    grouped = {}
    for e in entries:
        key = e['class_key']
        if key not in grouped:
            grouped[key] = {'eval_id': e['eval_id'], 'topk': {}}
        # normalize tol and K
        tol = e['tol']
        K = e['K']
        if tol is None or K is None:
            continue
        grouped[key]['topk'].setdefault((tol, K), e['pairs'])

    results = []
    for key, meta in grouped.items():
        # index map by known filename stem in maps
        # Try to find a map whose stem is contained in key
        perm = None
        candidates = [k for k in index_maps.keys() if k in key or key in k]
        if candidates:
            perm = index_maps[candidates[0]]
        per_class = {
            'class_key': key,
            'eval_id': meta['eval_id'],
            'jaccards': {},
            'counts': {},
            'index_map_applied': bool(perm is not None)
        }
        for tol in TOLS:
            for K in K_GRID:
                mine_set = mine[(tol, K)]
                contrib_pairs = meta['topk'].get((tol, K))
                if contrib_pairs is None:
                    # If a larger K was provided, allow truncation
                    larger = [meta['topk'].get((tol, KK)) for KK in K_GRID if KK and meta['topk'].get((tol, KK))]
                    if larger:
                        # pick the largest available and truncate
                        contrib_pairs = max(larger, key=len)[:K]
                if contrib_pairs is None:
                    jv = None
                    cnt = 0
                else:
                    mapped = apply_index_map(contrib_pairs, perm)
                    mapped = mapped[:K]
                    jv = jaccard(mine_set, mapped)
                    cnt = len(mapped)
                per_class['jaccards'][f'{tol}_K{K}'] = jv
                per_class['counts'][f'{tol}_K{K}'] = cnt
        results.append(per_class)

        # Write per-class result
        out_name = f"{key}_compare_v2_1_refresh.json"
        write_json(os.path.join(OUT_DIR, out_name), per_class)

    summary = {
        'generated_at': ts(),
        'classes_processed': len(results),
        'k_grid': K_GRID,
        'tols': TOLS,
        'notes': 'Aggregator v2.1 refresh — Jaccards vs Noesis snapshot Top-K; index maps applied when provided.',
        'results': results
    }
    write_json(SUMMARY_PATH, summary)
    freeze_name = f"appendix_E_summary_v2_1_refresh_{ts()}.json"
    write_json(os.path.join(FREEZE_DIR, freeze_name), summary)

# ---- Entry point ----
def construct_packing():
    c0, r0 = load_snapshot()
    try:
        aggregate_and_compare(c0, r0)
    except Exception as e:
        # Minimal failure log
        err = {'generated_at': ts(), 'error': str(e)}
        write_json(os.path.join(OUT_DIR, 'aggregator_v2_1_error.json'), err)
    # Return baseline packing with tiny shrink
    r = np.maximum(r0 - 1e-9, 1e-12)
    return c0.astype(float), r.astype(float)
